window.OVA_CONTENT={"slug":"seccion-06-microbiologia-aplicada-y-bioseguridad","title":"Microbiología aplicada y bioseguridad","minutes":50,"summary":"Diferencia microorganismos benéficos, alterantes y patógenos y controla sus condiciones en procesos agroindustriales.","objective":"Analizar aplicaciones microbianas, bioinsumos, riesgos y trazabilidad.","stages":[{"eyebrow":"Diversidad","title":"1. Bacterias, hongos y levaduras","reading":"Las bacterias son procariotas. Los hongos son eucariotas y pueden ser unicelulares o multicelulares; las levaduras son hongos unicelulares con importancia fermentativa.","application":"La clasificación orienta preguntas sobre estructura y metabolismo, pero la función depende de especie, cepa y contexto.","activity":{"type":"match","question":"Relaciona grupo y característica.","pairs":[{"label":"Bacterias","value":"procariotas","option":"Procariotas"},{"label":"Hongos","value":"eucariotas","option":"Eucariotas"},{"label":"Levaduras","value":"unicelulares","option":"Hongos unicelulares"}],"answer":["procariotas","eucariotas","unicelulares"],"success":"La estructura básica ayuda a diferenciar grupos."}},{"eyebrow":"Crecimiento","title":"2. Condiciones que cambian la actividad","reading":"Temperatura, pH, disponibilidad de agua, oxígeno, nutrientes y tiempo determinan si una población crece o permanece limitada. Controlar estas variables es parte del diseño del proceso.","application":"El mismo microorganismo puede ser útil en un fermentador y causar alteración si aparece fuera del sistema controlado.","activity":{"type":"multi","question":"Selecciona condiciones de crecimiento.","options":["Temperatura","pH","Actividad de agua","Morfología colonial observada al terminar el proceso"],"answer":[0,1,2],"success":"El ambiente determina la actividad microbiana."}},{"eyebrow":"Función","title":"3. Beneficio, alteración o peligro","reading":"Muchos microorganismos fermentan, reciclan nutrientes o controlan otros organismos. Otros alteran productos o causan enfermedad. La función debe establecerse con identificación, evidencia y contexto.","application":"La presencia microbiana no equivale automáticamente a contaminación peligrosa. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"choice","question":"¿Cuál afirmación es correcta?","options":["La función depende del organismo y del contexto","La clasificación taxonómica determina por sí sola si el efecto será beneficioso","La presencia de fermentación demuestra que no existen riesgos microbiológicos"],"answer":[0],"success":"La microbiología aplicada distingue funciones y riesgos."}},{"eyebrow":"Fermentación","title":"4. Un proceso que debe controlarse","reading":"En una fermentación, cultivo, sustrato, temperatura, tiempo y condiciones sanitarias influyen en acidez, aroma, textura y estabilidad. La repetibilidad depende de estandarización y registros.","application":"Un cultivo iniciador sin trazabilidad puede explicar diferencias entre lotes. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"order","question":"Ordena un control básico del proceso.","items":["Verificar cultivo y lote","Preparar sustrato y condiciones","Inocular","Monitorear tiempo, temperatura y pH","Registrar y evaluar producto"],"answer":[0,1,2,3,4],"success":"La calidad depende del control de todo el proceso."}},{"eyebrow":"Caso integrado","title":"5. Bioinsumos con evidencia","reading":"Biofertilizantes y biocontroladores pueden apoyar nutrición o manejo de plagas. Antes de adoptarlos deben revisarse identidad, registro aplicable, calidad, almacenamiento, eficacia y compatibilidad.","application":"Que un producto sea natural no elimina los riesgos ni la necesidad de seguimiento. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"choice","question":"¿Qué propuesta es responsable?","options":["Prueba controlada con producto verificado y registros","Aplicación en una parcela completa con observación visual como único seguimiento","Uso de un cultivo local sin verificar identidad porque ya se adaptó al ambiente"],"answer":[0],"success":"Los bioinsumos requieren control y trazabilidad."}},{"eyebrow":"Dinámica","title":"6. Crecimiento microbiano y tiempo","reading":"En condiciones favorables una población atraviesa adaptación, crecimiento rápido, estabilidad y declive. Temperatura, pH, agua disponible y sustrato cambian la velocidad.","application":"Controlar un proceso exige reconocer si se busca estimular un cultivo útil o limitar un contaminante.","visual":{"label":"Crecimiento microbiano y tiempo","items":["Condición","Crecimiento","Muestreo","Interpretación"]},"activity":{"type":"choice","question":"¿Qué inferencia es más prudente ante un aumento microbiano inesperado?","options":["Revisar tiempo, temperatura, actividad de agua y puntos de contaminación","Atribuirlo a una especie concreta sin identificación adicional","Concluir que todo microorganismo presente representa el mismo peligro"],"answer":[0],"success":"El patrón orienta la investigación, pero la identificación y el riesgo requieren evidencia adicional."}},{"eyebrow":"Muestreo","title":"7. Una muestra debe representar el proceso","reading":"La distribución microbiana puede ser heterogénea. Sitio, momento, tamaño de muestra, técnica aséptica, transporte y conservación afectan el resultado.","application":"Un resultado negativo en una muestra mal diseñada no demuestra ausencia en todo el lote. La organización debe registrar condiciones, controles y resultados para convertir el conocimiento biológico en una decisión productiva verificable.","activity":{"type":"multi","question":"¿Qué decisiones fortalecen un plan de muestreo microbiológico?","options":["Definir puntos según el flujo y el riesgo","Incluir momentos representativos del proceso","Controlar toma, transporte y trazabilidad","Tomar siempre una única muestra del lugar más accesible"],"answer":[0,1,2],"success":"La representatividad se diseña antes del análisis de laboratorio."}},{"eyebrow":"Respuesta","title":"8. Del hallazgo a la acción de bioseguridad","reading":"La respuesta debe proteger personas, producto y ambiente sin destruir evidencia. Incluye contención, comunicación, confirmación, corrección y verificación.","application":"Una desinfección inmediata sin registro ni muestreo puede impedir identificar la fuente y favorecer recurrencias.","activity":{"type":"order","question":"Ordena una respuesta ante contaminación no esperada.","items":["Delimitar y contener el área o lote","Registrar y tomar muestras representativas","Confirmar e investigar la fuente","Corregir proceso, limpieza o barreras","Verificar eficacia y actualizar prevención"],"answer":[0,1,2,3,4],"success":"La bioseguridad combina control inmediato con aprendizaje preventivo."}}],"number":"06","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};